seq = ""
with open("region.fasta") as f:
    for line in f:
        if line.startswith(">"):
            header = line.strip()
        else:
            seq += line.strip()
seq = seq.upper()
print("Header:", header)
print("Length:", len(seq))
print("Composition:", {b: seq.count(b) for b in "ACGT"})
print("GC %:", round(100*(seq.count('G')+seq.count('C'))/len(seq),2))

def revcomp(s):
    return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

codon = {}
bases="TCAG"
aas="FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG"
i=0
for a in bases:
    for b in bases:
        for c in bases:
            codon[a+b+c]=aas[i]; i+=1

def translate(s):
    return "".join(codon.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))

# find ORFs in 6 frames
def find_orfs(s, strand, min_aa=60):
    orfs=[]
    L=len(s)
    for frame in range(3):
        # scan for ATG...stop
        i=frame
        prot=translate(s[frame:])
        # split by stops
        start=0
        for j,aa in enumerate(prot+"*"):
            if aa=='*':
                seg=prot[start:j]
                if len(seg)>=min_aa:
                    orfs.append((strand, frame, start*3, (start+len(seg))*3+3, seg))
                start=j+1
    return orfs

