def orfs_atg(s,strand,minaa=50):
    out=[]
    for f in range(3):
        p=tr(s[f:])
        j=0
        while j < len(p):
            if p[j]=='M':
                k=j
                while k<len(p) and p[k]!='*': k+=1
                if k-j>=minaa:
                    out.append((strand,f,j*3+f,(k+1)*3+f,p[j:k]))
                j=k+1 if k<len(p) else k
            else:
                j+=1
    return out

